		db.Choice("back5", "\"Something else.\"", "hub", "", "", "", "", "", "", "", "");
		db.Conv("wanderer.trader.prices", "wanderer:trader", "", "Ask what sells these days.", 4, 0, "plain");
		db.Node("start");
		db.Say("", "\"Batteries, always. Salt, since the shop in {here} went. Boots in your size, never.\"");
		db.Say("", "\"Jewellery sells to the Red Hand. Don't ask me what they do with it. They weigh it.\"");
		db.Choice("cheap", "\"Anything cheap?\"", "cheap", "", "", "", "", "", "", "", "");
		db.Choice("other", "\"Something else.\"", "hub", "", "", "", "", "", "", "", "");
		db.Node("cheap");
		db.Say("", "\"Advice. Here's some: never buy a tin that's been opened and closed again.\"");
		db.Choice("back1", "\"Something else.\"", "hub", "", "", "", "", "", "", "", "");
